<?php
declare(strict_types=1);session_start();require_once 'db.php';if(!isset($_SESSION['admin'])){header('Location: admin_login.php');exit;}function e(?string $v):string{return htmlspecialchars($v??'',ENT_QUOTES,'UTF-8');}
if(!isset($_SESSION['inspection_admin_csrf']))$_SESSION['inspection_admin_csrf']=bin2hex(random_bytes(32));$csrf=$_SESSION['inspection_admin_csrf'];$msg='';$err='';
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['review_inspection'])){$id=(int)($_POST['inspection_id']??0);$d=(string)($_POST['decision']??'');$r=trim((string)($_POST['supervisor_remarks']??''));if(!hash_equals($csrf,(string)($_POST['csrf_token']??'')))$err='Permintaan tidak sah.';elseif($id<1||!in_array($d,['Verified','Rejected'],true))$err='Maklumat tidak sah.';elseif($d==='Rejected'&&$r==='')$err='Catatan diperlukan untuk penolakan.';else{$s=$conn->prepare("UPDATE asset_inspections SET inspection_status=?,supervisor_remarks=?,verified_by=?,verified_at=NOW() WHERE id=?");$admin=(string)$_SESSION['admin'];$s->bind_param('sssi',$d,$r,$admin,$id);$msg=$s->execute()?'Pemeriksaan berjaya dikemas kini.':'Kemas kini gagal.';$s->close();}}
$rows=[];$r=$conn->query("SELECT i.*,a.asset_code,a.asset_name,a.location,s.full_name staff_name FROM asset_inspections i JOIN assets a ON a.id=i.asset_id JOIN staff s ON s.id=i.staff_id ORDER BY FIELD(i.inspection_status,'Submitted','Rejected','Verified'),i.created_at DESC");if($r){while($x=$r->fetch_assoc())$rows[]=$x;}$conn->close();
?>
<!doctype html><html lang="ms"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Asset Inspections</title><link rel="stylesheet" href="css/pms.css?v=8"><link rel="stylesheet" href="css/pms_asset_qr.css?v=1"></head><body class="pms-body"><div class="pms-shell"><aside class="pms-sidebar"><div class="pms-brand"><img src="images/logo.png?v=4" alt="V23"><div><strong>V23 Malawa Ria</strong><span>Property Management System</span></div></div><nav class="pms-nav"><a href="admin_dashboard.php">Dashboard</a><a href="admin_assets.php">Asset Management</a><a href="admin_asset_qr.php">Asset QR Codes</a><a class="active" href="admin_asset_inspections.php">Asset Inspections</a></nav></aside><main class="pms-main"><header class="pms-topbar"><div><h1>Asset Inspections</h1><p>Semak pemeriksaan yang dihantar pekerja.</p></div></header><?php if($msg):?><div class="pms-alert-success"><?=e($msg)?></div><?php endif;?><?php if($err):?><div class="pms-alert-error"><?=e($err)?></div><?php endif;?><section class="pms-card pms-table-wrap"><table class="pms-table"><thead><tr><th>Rujukan</th><th>Aset</th><th>Pekerja</th><th>Tarikh</th><th>Keadaan</th><th>Status</th><th>Tindakan</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="7">Tiada pemeriksaan.</td></tr><?php else:foreach($rows as $x):$id=(int)$x['id'];?><tr><td><strong><?=e((string)$x['inspection_reference'])?></strong></td><td><?=e((string)$x['asset_code'])?><br><small><?=e((string)$x['asset_name'])?></small></td><td><?=e((string)$x['staff_name'])?></td><td><?=e((string)$x['inspection_date'])?></td><td><?=e((string)$x['condition_result'])?></td><td><?=e((string)$x['inspection_status'])?></td><td><button class="pms-button-secondary" onclick="document.getElementById('i<?=$id?>').style.display='table-row'">Semak</button></td></tr><tr id="i<?=$id?>" style="display:none"><td colspan="7"><div class="inspection-asset-banner"><h2><?=e((string)$x['asset_name'])?></h2><p>Lokasi: <?=e((string)$x['location'])?></p><p>Findings: <?=nl2br(e((string)($x['findings']??'-')))?></p><p>Action: <?=nl2br(e((string)($x['action_taken']??'-')))?></p></div><form method="post" class="pms-form-grid"><input type="hidden" name="csrf_token" value="<?=e($csrf)?>"><input type="hidden" name="inspection_id" value="<?=$id?>"><input type="hidden" name="decision" value=""><div class="pms-form-group pms-form-group-full"><label>Supervisor Remarks</label><textarea name="supervisor_remarks"><?=e((string)($x['supervisor_remarks']??''))?></textarea></div><div class="pms-form-group pms-form-group-full" style="display:flex;gap:10px"><button name="review_inspection" class="pms-button" onclick="this.form.decision.value='Verified'">Verify</button><button name="review_inspection" class="pms-button-danger" onclick="this.form.decision.value='Rejected'">Reject</button><?php if((int)$x['work_order_required']===1):?><a class="pms-button-secondary" href="create_work_order.php?asset_id=<?=(int)$x['asset_id']?>">Create Work Order</a><?php endif;?></div></form></td></tr><?php endforeach;endif;?></tbody></table></section></main></div></body></html>
